import torch
import tilelang as T
from tilelang.jit import prim_func
from tilelang import Index
from tilelang import arith, math, linalg

class Model(nn.Module):
    def __init__(self, dim):
        super(Model, self).__init__()
        self.dim = dim

    def forward(self, x):
        return torch.cumsum(x, dim=self.dim)

@prim_func
def cumsum_kernel(
    A: T.Buffer((32768, 32768), "float16"),
    B: T.Buffer((32768, 32768), "float16")
):
    # Define indices
    i = T.axis.spatial(32768, 0)
    j = T.axis.spatial(32768, 0)

    # Initialize accumulator with zero
    acc = T.alloc_buffer((1,), "float32")
    acc[0] = 0.0

    # Perform cumulative sum along the last dimension (dim=1)
    with T.for_range(0, 32768, name="k") as k:
        # Accumulate values from index 0 to k
        acc[0] = acc[0] + T.cast(A[i, k], "float32")
        # Store result at position j=k
        if k == j:
            B[i, j] = T.cast(acc[0], "float16")

def get_inputs():
    return [torch.rand(32768, 32768, dtype=torch.float16)]

def get_init_inputs():
    return [1]
